DO $$ DECLARE r record; allowed text[] := ARRAY['admin_link_softphone_by_email','admin_link_softphone_by_extension_email','audit_exec_sql','can_access_org','can_manage_pbx_for_client','create_planipret_sip_secret','ensure_general_channel','get_accessible_org_ids','get_message_edit_history','get_message_receipts','get_my_extension_summary','get_org_by_fusionpbx_domain','get_org_pbx_mapping','get_unread_counts','get_user_organization_ids','has_role','hide_chat_message','is_lemtel_admin','is_lemtel_member','is_lemtel_only','is_master_admin','is_planipret_admin','is_planipret_member','is_planipret_only','is_super_admin','lemtel_can_grant_app_access','log_agent_access','mark_messages_read','mark_voicemail_read','my_platform_access_allowed','pin_chat_message','pp_audit_realtime_check','pp_claim_call','read_planipret_sip_secret','relink_my_softphone_user','resolve_org_by_domain_name','run_security_audit','search_chat','search_chat_users','set_softphone_platform_access','setup_customer_organization','setup_new_user_organization','try_lock_call_intel','unhide_chat_message','unlock_call_intel','unpin_chat_message','verify_tenant_isolation']; BEGIN FOR r IN SELECT n.nspname, p.proname, pg_get_function_identity_arguments(p.oid) AS args FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prosecdef AND n.nspname='public' AND NOT (p.proname = ANY(allowed)) LOOP EXECUTE format('REVOKE EXECUTE ON FUNCTION %I.%I(%s) FROM authenticated', r.nspname, r.proname, r.args); END LOOP; END $$;